    body {
      margin: 0;
      font-family: Inter, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
      background: linear-gradient(180deg, #0b1020 0%, #0f1730 100%);
      color: var(--text);
    }
    .container { max-width: 1320px; margin: 0 auto; padding: 24px; }
    .hero {
      background: linear-gradient(135deg, #1c2b55 0%, #0e1530 100%);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 24px;
      margin-bottom: 18px;
    }
    h1 { margin: 0 0 8px; font-size: 28px; }
    .sub { color: var(--muted); margin-bottom: 12px; }
    nav a { color: var(--accent-2); text-decoration: none; margin-right: 14px; font-size: 14px; }
    .kpi-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 12px;
      margin: 16px 0 24px;
    }
    .kpi {
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 14px;
    }
    .kpi .label { color: var(--muted); font-size: 12px; margin-bottom: 6px; }
    .kpi .value { font-size: 24px; font-weight: 700; }
    .kpi .unit { font-size: 12px; color: var(--muted); }
    section {
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 18px;
      margin-bottom: 16px;
    }
    h2 { margin-top: 0; font-size: 20px; }
    .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
    .chart { height: 340px; background: var(--panel-2); border: 1px solid var(--border); border-radius: 10px; }
    .insight {
      margin-top: 10px;
      background: #0f1836;
      border-left: 4px solid var(--accent);
      padding: 10px 12px;
      color: #d4ddf7;
      border-radius: 6px;
      font-size: 14px;
    }
    table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 13px; }
    th, td { border-bottom: 1px solid var(--border); padding: 8px; text-align: left; }
