      <div class="grid-2">
        <div id="chart_renewable_weather_slot" class="chart"></div>
        <div id="chart_price_slot" class="chart"></div>
      </div>
      <div id="renewable-insight" class="insight"></div>
    </section>

    <section id="vehicle-charging-behavior">
      <h2>Vehicle Charging Behavior & Session Profiles</h2>
      <div class="grid-2">
        <div id="chart_vehicle_profile" class="chart"></div>
        <div id="chart_priority_dist" class="chart"></div>
      </div>
      <div id="vehicle-insight" class="insight"></div>
    </section>

    <section id="optimization-recommendations">
      <h2>Optimization Insights & Recommendations</h2>
      <div id="recommendations" class="insight" style="border-left-color:#56ccf2"></div>
    </section>

    <div class="footer">Source: <code>/app/benchmark/data.csv</code> (all figures derived directly from dataset). Generated on <span id="gen-date"></span>.</div>
  </div>

  <script>
    async function run() {
      const metrics = await fetch('./metrics.json').then(r => r.json());

      const fmt = (n, d=2) => Number(n).toLocaleString(undefined, {maximumFractionDigits:d, minimumFractionDigits:d});
      const k = metrics.kpis;
      document.getElementById('gen-date').textContent = new Date().toISOString();

      const kpiItems = [
        ['Average Waiting Time', fmt(k.avg_waiting_time), 'min'],
        ['Average Energy / Session', fmt(k.avg_energy), 'kWh'],
        ['Mean Station Load', fmt(k.mean_station_load), 'kW'],
        ['Renewable Energy Ratio', fmt(k.renewable_ratio), 'share'],
        ['Mean Optimization Reward', fmt(k.mean_opt_reward), 'score']
      ];
      document.getElementById('kpi-banner').innerHTML = kpiItems.map(([l,v,u]) =>
        `<div class="kpi"><div class="label">${l}</div><div class="value">${v}</div><div class="unit">${u}</div></div>`
      ).join('');

      const byLocSlot = metrics.by_location_timeslot;
      const locs = [...new Set(byLocSlot.map(d=>d.location_type))];
      const slots = [...new Set(byLocSlot.map(d=>d.time_slot))];

      const barTraces = locs.map(loc => ({
        x: slots,
        y: slots.map(s => (byLocSlot.find(d => d.location_type===loc && d.time_slot===s) || {sessions:0}).sessions),
        name: loc,
        type: 'bar'
      }));
      Plotly.newPlot('chart_sessions_loc_slot', barTraces, {
        barmode:'group',
        title:'Session Volume by Location Type & Time Slot',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const topStations = metrics.top_stations_demand;
      Plotly.newPlot('chart_top_stations', [{
        x: topStations.map(d=>d.station_id),
        y: topStations.map(d=>d.sessions),
        mode:'lines+markers',
        name:'Sessions',
        line:{color:'#56ccf2'}
      }], {
        title:'Top Stations by Session Throughput',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const wt = metrics.wait_heatmap;
      const qh = metrics.queue_heatmap;
      const zWait = locs.map(loc => slots.map(s => {
        const r = wt.find(d=>d.location_type===loc && d.time_slot===s); return r ? r.waiting_time : null;
      }));
      const zQueue = locs.map(loc => slots.map(s => {
        const r = qh.find(d=>d.location_type===loc && d.time_slot===s); return r ? r.queue_length : null;
      }));

      Plotly.newPlot('chart_wait_heatmap', [{x:slots, y:locs, z:zWait, type:'heatmap', colorscale:'YlOrRd'}], {
        title:'Average Waiting Time Heatmap (min)',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      Plotly.newPlot('chart_queue_heatmap', [{x:slots, y:locs, z:zQueue, type:'heatmap', colorscale:'Portland'}], {
        title:'Average Queue Length Heatmap',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const wbt = metrics.wait_by_traffic;
      const traff = [...new Set(wbt.map(d=>d.traffic_density))];
      const wTrafficTraces = traff.map(t => ({
        x: slots,
        y: slots.map(s => (wbt.find(d=>d.traffic_density===t && d.time_slot===s)||{waiting_time:null}).waiting_time),
        mode:'lines+markers', name:t
      }));
      Plotly.newPlot('chart_wait_traffic', wTrafficTraces, {
        title:'Waiting Time by Traffic Density & Time Slot',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const wbv = metrics.wait_by_vehicle;
      const vehTop = [...new Set(wbv.map(d=>d.vehicle_type))].slice(0,8);
      const wVehTraces = vehTop.map(v => ({
        x: slots,
        y: slots.map(s => (wbv.find(d=>d.vehicle_type===v && d.time_slot===s)||{waiting_time:null}).waiting_time),
        mode:'lines', name:v
      }));
      Plotly.newPlot('chart_wait_vehicle', wVehTraces, {
        title:'Waiting Time by Vehicle Type & Time Slot',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const eds = metrics.energy_load_day_slot;
      const days = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
      const zLoad = days.map(day => slots.map(s => {
        const r = eds.find(d=>d.day_of_week===day && d.time_slot===s); return r ? r.station_load : null;
      }));
      Plotly.newPlot('chart_energy_day_slot', [{x:slots,y:days,z:zLoad,type:'heatmap',colorscale:'Viridis'}], {
        title:'Mean Station Load by Day & Time Slot (kW)',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const lvp = metrics.load_vs_power;
      Plotly.newPlot('chart_load_power', [{
        x: lvp.map(d=>d.charging_power_kW), y:lvp.map(d=>d.station_load),
        mode:'markers+lines', marker:{size:lvp.map(d=>Math.max(6, d.sessions/40)), color:'#3ddc97'}, name:'Station Load'
      }], {
        title:'Station Load vs Charging Power Level',
        xaxis:{title:'Charging Power (kW)'}, yaxis:{title:'Mean Station Load (kW)'},
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const rws = metrics.renewable_weather_slot;
      const weathers = [...new Set(rws.map(d=>d.weather_condition))];
      const zRen = weathers.map(w=>slots.map(s=>{ const r=rws.find(d=>d.weather_condition===w&&d.time_slot===s); return r? r.renewable_energy_ratio:null; }));
      Plotly.newPlot('chart_renewable_weather_slot', [{x:slots,y:weathers,z:zRen,type:'heatmap',colorscale:'Blues'}], {
        title:'Renewable Energy Ratio by Weather & Time Slot',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const pds = metrics.price_demand_slot;
      Plotly.newPlot('chart_price_slot', [
        {x:pds.map(d=>d.time_slot), y:pds.map(d=>d.electricity_price), type:'bar', name:'Electricity Price', yaxis:'y1'},
        {x:pds.map(d=>d.time_slot), y:pds.map(d=>d.charging_demand), type:'scatter', mode:'lines+markers', name:'Charging Demand', yaxis:'y2'}
      ], {
        title:'Dynamic Pricing vs Charging Demand by Time Slot',
        yaxis:{title:'Price'}, yaxis2:{title:'Demand', overlaying:'y', side:'right'},
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const vp = metrics.vehicle_profiles;
      Plotly.newPlot('chart_vehicle_profile', [{
        x: vp.map(d=>d.vehicle_type),
        y: vp.map(d=>d.energy_consumed_kWh),
        type:'bar',
        marker:{color:'#ffb020'},
        name:'Avg Energy'
      }], {
        title:'Average Energy per Session by Vehicle Type (kWh)',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const pd = metrics.priority_dist;
      Plotly.newPlot('chart_priority_dist', [{
        labels: pd.map(d=>d.charging_priority), values: pd.map(d=>d.sessions), type:'pie', hole:.45
      }], {
        title:'Charging Priority Distribution',
        paper_bgcolor:'rgba(0,0,0,0)', plot_bgcolor:'rgba(0,0,0,0)', font:{color:'#dce6ff'}
      }, {displayModeBar:false, responsive:true});

      const maxWait = byLocSlot.reduce((a,b)=> a.waiting_time>b.waiting_time?a:b);
      const maxQueue = byLocSlot.reduce((a,b)=> a.queue_length>b.queue_length?a:b);
      const bestRen = byLocSlot.reduce((a,b)=> a.renewable_energy_ratio>b.renewable_energy_ratio?a:b);
      const bestReward = byLocSlot.reduce((a,b)=> a.optimization_reward>b.optimization_reward?a:b);

      document.getElementById('station-insight').innerHTML =
        `Top throughput stations concentrate demand across location segments, with clear time-slot concentration effects. Highest-volume station in top list: <b>${topStations[0].station_id}</b> (${fmt(topStations[0].sessions,0)} sessions among ranked subset), indicating a targeted capacity planning candidate.`;

      document.getElementById('queue-insight').innerHTML =
        `Queue pressure is most acute at <b>${maxWait.location_type} · ${maxWait.time_slot}</b> (avg wait ${fmt(maxWait.waiting_time)} min) and longest queue at <b>${maxQueue.location_type} · ${maxQueue.time_slot}</b> (avg queue ${fmt(maxQueue.queue_length)}). This is the primary customer-experience bottleneck cluster for intervention.`;

      document.getElementById('energy-insight').innerHTML =
        `Grid stress tracks charging intensity by power tier and temporal concentration. Focus load-balancing controls on high-load day/slot cells and power tiers where station load steepens faster than throughput gain.`;

      document.getElementById('renewable-insight').innerHTML =
        `Best renewable capture in this dataset appears at <b>${bestRen.location_type} · ${bestRen.time_slot}</b> (renewable ratio ${fmt(bestRen.renewable_energy_ratio)}). Correlations: price↔renewables = <b>${fmt(metrics.price_vs_renewable,3)}</b>, price↔demand = <b>${fmt(metrics.price_vs_demand,3)}</b>, reward↔renewables = <b>${fmt(metrics.reward_vs_renewable,3)}</b>, reward↔price = <b>${fmt(metrics.reward_vs_price,3)}</b>.`;

      document.getElementById('vehicle-insight').innerHTML =
        `Vehicle sessions show distinct energy and duration profiles by type; align charger allocation and queue policies with higher-intensity segments to reduce peak-time dwell and improve charger turnover.`;

      document.getElementById('recommendations').innerHTML = `
        <b>Actionable interventions synthesized across sections:</b><br><br>
        1) <b>Queue hot-zone mitigation:</b> prioritize staffing, bay expansion, or virtual queue controls at <b>${maxWait.location_type} · ${maxWait.time_slot}</b> and <b>${maxQueue.location_type} · ${maxQueue.time_slot}</b>.<br>
        2) <b>Time-slot load shifting:</b> introduce stronger off-peak price incentives where wait and queue exceed network averages; pair with user messaging nudges in mobile apps.<br>
        3) <b>Renewable-aware charging incentives:</b> trigger discounted tariffs during high-renewable windows (notably slots similar to <b>${bestRen.time_slot}</b>) to increase green-energy utilization.<br>
        4) <b>Power-tier dispatch strategy:</b> dynamically match high-energy vehicle cohorts to higher-power chargers during low-grid-stress windows to protect peak-period stability.<br>
        5) <b>Reward-driven control loop:</b> use optimization reward trend as a daily KPI gate; pilot interventions where reward is below network mean (<b>${fmt(k.mean_opt_reward)}</b>) and evaluate uplift weekly.
      `;

      const tableRows = topStations.slice(0,10).map(d => `
        <tr>
          <td>${d.station_id}</td>
          <td>${d.location_type}</td>
          <td>${fmt(d.sessions,0)}</td>
          <td>${fmt(d.charging_demand,2)}</td>
          <td>${fmt(d.waiting_time,2)}</td>
          <td>${fmt(d.queue_length,2)}</td>
        </tr>
      `).join('');
      document.getElementById('top-stations-table').innerHTML = `
        <table>
          <thead><tr><th>Station</th><th>Location Type</th><th>Sessions</th><th>Mean Demand</th><th>Mean Wait (min)</th><th>Mean Queue</th></tr></thead>
          <tbody>${tableRows}</tbody>
        </table>
      `;
    }
    run();
  </script>
</body>
</html>
